    def __init__(self):
        self.trace = 'check-charge'

def _base():
    return os.environ.get(settings.S.secret_env('url'), 'http://localhost:7700').rstrip('/')

def _key():
    return os.environ.get(settings.S.secret_env('api', 'key'), '')

def _headers(ctx):
    return {'Authorization': 'Bearer ' + _key(), 'Content-Type': 'application/json'}

def _get(path, ctx):
    req = urllib.request.Request(_base() + path, headers=_headers(ctx), method='GET')
    try:
        with urllib.request.urlopen(req, timeout=3.0) as r:
            return json.loads(r.read().decode())
    except urllib.error.HTTPError as e:
        print(f'HTTP Error {e.code}: {e.read().decode()}')
        return None
    except Exception as e:
        print(f'Error: {e}')
        return None

